"""Persistent shared JSON cache for public demonstration profiles."""
import json
import os
import time

from app.config import CACHE_PATH, CACHE_TTL


def get_or_load(key, loader, now=None):
    """Return cached value if fresh, otherwise call loader and store result.

    The cache file is a JSON dict of ``{key: {stored_at, value}}`` entries,
    reusable across processes.  *now* defaults to ``time.time()``.
    """
    if now is None:
        now = time.time()

    # Try to read existing cache
    store = {}
    if os.path.exists(CACHE_PATH):
        with open(CACHE_PATH, "r") as f:
            try:
                store = json.load(f)
            except (json.JSONDecodeError, ValueError):
                store = {}

    # Check for a fresh entry
    if key in store:
        entry = store[key]
        if now - entry["stored_at"] < CACHE_TTL:
            return entry["value"]

    # Call loader for a fresh value and persist
    value = loader()
    store[key] = {"stored_at": now, "value": value}

    os.makedirs(os.path.dirname(CACHE_PATH), exist_ok=True)
    with open(CACHE_PATH, "w") as f:
        json.dump(store, f)

    return value

